import { execution } from '@dynatrace-sdk/automation-utils';
import { eventsClient, EventIngestEventType } from '@dynatrace-sdk/client-classic-environment-v2';
import { httpClient } from '@dynatrace-sdk/http-client';

// CNO Interface Degradation RCA (Lane A) — partial interface failure on an otherwise-UP device.
// A down interface reports cno.if.oper_status==2 (RAW ifOperStatus; up==1). admin_status==1 filters
// to enabled ports, so admin-down/disabled ports (a large normal baseline) never false-fire. The
// device keeps answering SNMP, so the device/chain workflow (Lane B) correctly stays silent.
// Emits ONE consolidated card per partial device — down-interface list in properties, STABLE title
// so Davis renews a single problem instead of one-per-interface (no storm). Davis CoPilot adds a
// best-effort narrative (cause / config-change contribution / first action), same as Lane B.
export default async function ({ executionId }) {
  const ex = await execution(executionId);
  const cls = await ex.result('classify');
  const ents = await ex.result('entities');
  const evR = await ex.result('evidence');
  const norm = s => String(s || '').toLowerCase();

  const entOf = {};
  for (const r of ((ents && ents.records) || [])) {
    const d = norm(r['device']); if (d && r['entityId']) entOf[d] = r['entityId'];
  }

  const results = [];
  for (const r of ((cls && cls.records) || [])) {
    const device = norm(r['device']);
    const down = Number(r['down'] || 0);
    const up = Number(r['up'] || 0);
    const list = Array.isArray(r['down_list']) ? r['down_list'] : [];
    const entityId = entOf[device] || null;
    if (!device || down < 1) continue;

    const title = `Interface degradation on ${device}`;   // STABLE (dedup key) — detail in props
    const props = {
      'event.description': `${device} is UP but ${down} admin-enabled interface(s) are ` +
        `operationally down: ${list.join(', ') || '(unnamed)'}. ${up} enabled interface(s) still up. ` +
        `Disabled/admin-down ports are excluded (not a fault). Device reachable — no device-level ` +
        `outage, so Lane B stays silent.`,
      'cno.device': device,
      'cno.iface_down_count': String(down),
      'cno.iface_down_list': list.join(',') || '(unnamed)',
      'cno.iface_up_count': String(up),
      'cno.severity_hint': down >= 3 ? 'high' : 'low',
      'dt.event.group_label': `cno-iface-degradation-${device}`,
    };
    Object.keys(props).forEach(k => { if (!props[k]) delete props[k]; });

    // Davis CoPilot narrative — best effort; card keeps the deterministic detail if it fails.
    try {
      const _chg = (evR.records || []).filter(r2 => r2['src'] === 'network.config' && norm(r2['dev']) === device)
        .slice(0, 6).map(r2 => `${r2['ts']} config change on ${r2['dev']}: ${r2['msg']}`);
      const _log = (evR.records || []).filter(r2 => r2['src'] === 'cisco.syslog' && norm(r2['dev']) === device)
        .slice(0, 8).map(r2 => `${r2['ts']} syslog ${r2['dev']}: ${r2['msg']}`);
      const _ev = _chg.concat(_log).join('\n');
      const _prompt = `Network interface degradation. Device ${device} is UP and reachable via SNMP, ` +
        `but ${down} admin-enabled interface(s) are operationally down: ${list.join(', ')}. ${up} ` +
        `interface(s) remain up — this is a PARTIAL failure, NOT a device outage.` +
        (_ev ? `\n\nRecent evidence (config changes + syslog from ${device}):\n${_ev}` : '') +
        `\n\nIn 2-3 sentences: the most likely cause for these specific interfaces (cabling / SFP / ` +
        `far-end device / local port config), whether a recent config change on this device likely ` +
        `contributed, and one recommended first action. The device itself is reachable — do NOT ` +
        `describe it as down.`;
      const _r = await httpClient.send({ url: '/platform/davis/copilot/v1/skills/conversations:message', method: 'POST', body: { text: _prompt, context: [] }, headers: { 'Content-Type': 'application/json' } });
      if (_r.status < 300) { const _b = await _r.body('json'); const _t = _b && _b.text; if (_t) { props['cno.rca_narrative'] = String(_t).slice(0, 1200); props['event.description'] = 'Davis CoPilot - ' + String(_t).replace(/\n/g, ' ').slice(0, 460) + ' || ' + props['event.description']; } }
    } catch (e) { /* CoPilot best-effort */ }

    try {
      await eventsClient.createEvent({
        body: {
          eventType: EventIngestEventType.AvailabilityEvent,
          title,
          entitySelector: entityId ? `entityId("${entityId}")` : `type("network:device")`,
          timeout: 8,   // > 3-min poll -> re-post renews ONE problem; auto-resolves ~8m after recovery
          properties: props,
        },
      });
      results.push({ device, down, up, entityId: entityId || '(unresolved)' });
    } catch (e) {
      results.push({ device, error: String(e) });
    }
  }
  return { partialDevices: ((cls && cls.records) || []).length, emitted: results };
}
